function validate([n, edges, price, trips]) {
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n is between 1 and 50.';
  if (edges.length !== n - 1) return 'edges needs exactly n - 1 pairs.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const [a, b] of edges) {
    if (a < 0 || a >= n || b < 0 || b >= n) return 'Edge endpoints must be nodes 0 to n - 1.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'edges must form a tree (no cycles or repeated edges).';
    root[ra] = rb;
  }
  if (price.length !== n) return 'price needs one value per node.';
  if (price.some(p => p < 1 || p > 1000 || p % 2 !== 0)) return 'Each price is an even number from 2 to 1000.';
  if (trips.length < 1 || trips.length > 100) return 'trips needs 1 to 100 entries.';
  if (trips.some(t => t.length !== 2 || t.some(v => v < 0 || v >= n))) return 'Each trip is [start, end] with nodes 0 to n - 1.';
  return null;
}

