function minimumTotalPrice(n, edges, price, trips) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }
  const visits = new Array(n).fill(0);
  const markPath = (node, parent, target) => {
    if (node === target) {
      visits[node]++;
      return true;
    }
    for (const next of graph[node]) {
      if (next !== parent && markPath(next, node, target)) {
        visits[node]++;
        return true;
      }
    }
    return false;
  };
  for (const [start, end] of trips) {
    markPath(start, -1, end);
  }
  const solve = (node, parent) => {
    let keep = price[node] * visits[node];
    let halve = keep / 2;
    for (const next of graph[node]) {
      if (next === parent) continue;
      const [childKeep, childHalve] = solve(next, node);
      keep += Math.min(childKeep, childHalve);
      halve += childKeep;
    }
    return [keep, halve];
  };
  const [rootKeep, rootHalve] = solve(0, -1);
  return Math.min(rootKeep, rootHalve);
}

