function minimumTotalPrice(n, edges, price, trips) {
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const freq = new Array(n).fill(0);
  for (const [s, e] of trips) {
    const from = new Array(n).fill(-2);
    from[s] = -1;
    const q = [s];
    for (let h = 0; h < q.length; h++) for (const v of adj[q[h]]) if (from[v] === -2) { from[v] = q[h]; q.push(v); }
    for (let v = e; v !== -1; v = from[v]) freq[v]++;
  }
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    if (edges.some(([a, b]) => (mask >> a & 1) && (mask >> b & 1))) continue;
    let total = 0;
    for (let v = 0; v < n; v++) total += freq[v] * ((mask >> v & 1) ? price[v] / 2 : price[v]);
    best = Math.min(best, total);
  }
  return best;
}

