function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 10);
  const maxPrice = size === 'large' ? 500 : (rand() < 0.5 ? 5 : 50);
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const chain = rand() < 0.3;
  const edges = [];
  for (let i = 1; i < n; i++) {
    const parent = chain ? i - 1 : Math.floor(rand() * i);
    edges.push(rand() < 0.5 ? [order[i], order[parent]] : [order[parent], order[i]]);
  }
  const price = Array.from({ length: n }, () => 2 * (1 + Math.floor(rand() * maxPrice)));
  const m = size === 'large' ? 100 : 1 + Math.floor(rand() * 6);
  const trips = Array.from({ length: m }, () => [Math.floor(rand() * n), Math.floor(rand() * n)]);
  return [n, edges, price, trips];
}
